## C++ 代码实现

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <set>
#include <map>

using namespace std;

typedef long long ll;

// 函数：获取一个数在 k 进制下的第 i 位数字
// 类似于 (n / k^i) % k
ll get_digit(ll n, ll k, int i) {
    if (k < 2) return -1; // 进制必须 >= 2
    ll power_k = 1;
    for (int j = 0; j < i; ++j) {
        if (__builtin_mul_overflow(power_k, k, &power_k)) {
            // 溢出，说明 i 已经太大，该位数字为 0
            return 0; 
        }
    }
    if (power_k == 0) return 0; // 避免 k=1 的情况（虽然我们要求 k>=2）
    return (n / power_k) % k;
}

// 辅助函数：计算 a, b, c 在 k 进制下的所有位，直到最高位
// 返回 (max_i, a_i_list, b_i_list, c_i_list)
void get_k_digits(ll a, ll b, ll c, ll k, vector<ll>& a_digits, vector<ll>& b_digits, vector<ll>& c_digits) {
    a_digits.clear();
    b_digits.clear();
    c_digits.clear();

    ll temp_a = a, temp_b = b, temp_c = c;

    while (temp_a > 0 || temp_b > 0 || temp_c > 0) {
        a_digits.push_back(temp_a % k);
        b_digits.push_back(temp_b % k);
        c_digits.push_back(temp_c % k);

        temp_a /= k;
        temp_b /= k;
        temp_c /= k;
    }

    // 确保所有位向量长度一致 (如果某个数是 0，后面是 0)
    size_t max_len = max({a_digits.size(), b_digits.size(), c_digits.size()});
    while (a_digits.size() < max_len) a_digits.push_back(0);
    while (b_digits.size() < max_len) b_digits.push_back(0);
    while (c_digits.size() < max_len) c_digits.push_back(0);
}


void solve() {
    ll a, b, c;
    cin >> a >> b >> c;

    if (a == 0 && b == 0 && c == 0) {
        cout << -1 << endl;
        return;
    }

    ll D = a + b - c;

    if (D < 0) {
        cout << 0 << endl;
        return;
    }

    // Case D = 0: a + b = c
    if (D == 0) {
        // 此时需要所有 a_i + b_i < k。
        // 找到所有 a, b, c 的数字中最大的那个 D_max
        ll max_digit = 0;
        ll temp_a = a, temp_b = b, temp_c = c;

        while (temp_a > 0 || temp_b > 0 || temp_c > 0) {
            max_digit = max({max_digit, temp_a % 10, temp_b % 10, temp_c % 10}); // 粗略估计，因为不知道 k
            // 更好的做法是，如果 D=0，任何 k 使得 a, b, c 的所有位都小于 k 都是解。
            // 由于 a, b, c 是固定的十进制数，它们在任何 k > max_digit 的 k 进制表示中，
            // 最多只需要检查 k > max_digit (其中 max_digit 是 a, b, c 的最大十进制位数字，这是一个下界)
            // 实际上，如果 k > max(a, b, c) 的最高位数字，则所有位数字都小于 k。
            // 只要 a, b, c 非零，存在一个最大的位数字 D_max。所有 k > D_max 都满足条件，故无穷多解。

            temp_a /= 10;
            temp_b /= 10;
            temp_c /= 10;
        }

        // 确认存在无穷解的条件：a, b, c 中至少有一个非零 (已在开头排除 0,0,0)
        // 如果 D=0 且非零，则存在无穷多个 k 满足 a_i+b_i < k。
        cout << -1 << endl;
        return;
    }

    // Case D > 0: D = k * S, S = sum(q_i * k^i)
    set<ll> solutions;

    // 遍历 D 的所有因子 k (k >= 2)
    for (ll k = 2; k * k <= D; ++k) {
        if (D % k == 0) {
            // 检查因子 k
            ll k1 = k;
            ll S1 = D / k1;

            // 检查因子 D/k
            ll k2 = D / k;
            ll S2 = D / k2; // S2 = k

            // 检查 k1
            vector<ll> a_digits1, b_digits1, c_digits1;
            get_k_digits(a, b, c, k1, a_digits1, b_digits1, c_digits1);

            bool ok1 = true;
            ll calculated_S1 = 0;
            for (size_t i = 0; i < a_digits1.size(); ++i) {
                ll ai = a_digits1[i];
                ll bi = b_digits1[i];
                ll ci = c_digits1[i];

                // 1. 验证 c_i = (a_i + b_i) mod k
                if (ci != (ai + bi) % k1) {
                    ok1 = false;
                    break;
                }
                // 2. 计算 q_i 并累加 S
                ll qi = (ai + bi) / k1;
                calculated_S1 += qi * (ll)std::pow(k1, i);
            }

            if (ok1 && calculated_S1 == S1) {
                solutions.insert(k1);
            }

            // 检查 k2 (仅当 k1 != k2 时)
            if (k1 != k2) {
                vector<ll> a_digits2, b_digits2, c_digits2;
                get_k_digits(a, b, c, k2, a_digits2, b_digits2, c_digits2);

                bool ok2 = true;
                ll calculated_S2 = 0;
                for (size_t i = 0; i < a_digits2.size(); ++i) {
                    ll ai = a_digits2[i];
                    ll bi = b_digits2[i];
                    ll ci = c_digits2[i];

                    // 1. 验证 c_i = (a_i + b_i) mod k
                    if (ci != (ai + bi) % k2) {
                        ok2 = false;
                        break;
                    }
                    // 2. 计算 q_i 并累加 S
                    ll qi = (ai + bi) / k2;
                    calculated_S2 += qi * (ll)std::pow(k2, i);
                }

                if (ok2 && calculated_S2 == S2) {
                    solutions.insert(k2);
                }
            }
        }
    }

    // 检查 D 本身作为 k 的情况 (当 S=1 时)
    if (D >= 2) {
        ll k = D;
        ll S = 1; // 理论上 S 应该等于 1

        vector<ll> a_digits, b_digits, c_digits;
        get_k_digits(a, b, c, k, a_digits, b_digits, c_digits);

        bool ok = true;
        ll calculated_S = 0;
        for (size_t i = 0; i < a_digits.size(); ++i) {
            ll ai = a_digits[i];
            ll bi = b_digits[i];
            ll ci = c_digits[i];

            if (ci != (ai + bi) % k) {
                ok = false;
                break;
            }
            ll qi = (ai + bi) / k;
            calculated_S += qi * (ll)std::pow(k, i);
        }

        if (ok && calculated_S == S) {
            solutions.insert(k);
        }
    }


    cout << solutions.size() << endl;
}

int main() {
    // 优化输入输出
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    cin >> t;
    while (t--) {
        solve();
    }

    return 0;
}

```

