import React, { useState, useMemo, useCallback, ChangeEvent, FormEvent } from 'react';

// --- Types ---
export type Option = string;

// --- Constants (Mock Data for demonstration) ---
// In a real application, this would come from an API call.
const ALL_POSSIBLE_OPTIONS: Option[] = [
  'Apple', 'Banana', 'Cherry', 'Date', 'Elderberry', 'Fig', 'Grape', 'Honeydew',
  'Kiwi', 'Lemon', 'Mango', 'Nectarine', 'Orange', 'Peach', 'Plum', 'Quince',
  'Raspberry', 'Strawberry', 'Tangerine', 'Apricot', 'Avocado', 'Blueberry',
  // Add hundreds more items to test optimization
  ...Array.from({ length: 500 }, (_, i) => `Fruit_${i + 23}`)
];

// --- Validation Logic ---
// Simple validation: ensure the input matches one of the existing options.
const isValidInput = (value: string): boolean => {
  if (!value) return false; // Empty input is not valid for selection
  return ALL_POSSIBLE_OPTIONS.includes(value);
};

interface InputProps {
  label: string;
  placeholder?: string;
  // Optional: A function to run on successful change
  onChange?: (value: string) => void;
}

/**
 * A smart input component with an auto-completing, filterable dropdown.
 * Optimized for large option sets.
 */
const Input: React.FC<InputProps> = ({ label, placeholder = 'Start typing...', onChange }) => {
  const [inputValue, setInputValue] = useState<string>('');
  const [isOpen, setIsOpen] = useState<boolean>(false);
  const [error, setError] = useState<boolean>(false);

  // 1. Filtering Optimization: Use useMemo to prevent recalculation on every render
  const filteredOptions = useMemo(() => {
    if (!inputValue) return [];
    const lowerCaseInput = inputValue.toLowerCase();
    return ALL_POSSIBLE_OPTIONS.filter(option =>
      option.toLowerCase().includes(lowerCaseInput)
    );
  }, [inputValue]);

  // 2. Validation Check
  // Check validity immediately after input changes
  React.useEffect(() => {
    // Only validate if the input is not empty
    if (inputValue.length > 0) {
      setError(!isValidInput(inputValue));
    } else {
      setError(false); // Clear error when input is cleared
    }
  }, [inputValue]);


  // --- Handlers ---

  const handleInputChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    setInputValue(newValue);
    setError(!isValidInput(newValue)); // Immediate visual feedback
    setIsOpen(true); // Show dropdown immediately upon typing

    // Pass change up to parent component
    if (onChange) {
      onChange(newValue);
    }
  }, [onChange]);

  const handleSelectOption = useCallback((option: Option) => {
    setInputValue(option);
    setIsOpen(false);
    setError(false); // Selection is inherently valid

    if (onChange) {
      onChange(option);
    }
  }, [onChange]);

  const handleBlur = useCallback((e: FocusEvent<HTMLInputElement>) => {
    // Delay closing slightly to allow click events on dropdown items to register
    setTimeout(() => {
      setIsOpen(false);
    }, 150);
  }, []);

  // Handle Enter key press within the input field
  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && filteredOptions.length > 0) {
      // Select the first matching option on Enter
      handleSelectOption(filteredOptions[0]);
    } else if (e.key === 'Escape') {
      setIsOpen(false);
    }
  }, [filteredOptions, handleSelectOption]);


