  return (
    <div style={{ marginBottom: '20px' }}>
      <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>{label}</label>

      <div 
        style={{ 
          position: 'relative', 
          display: 'inline-block' 
        }}
        onBlur={handleBlur} // Use onBlur for closing when clicking outside
      >
        <input
