          <ul
            id="dropdown-list"
            style={{
              position: 'absolute',
              top: '100%', // Position right below the input
              left: 0,
              right: 0,
              border: '1px solid #ddd',
              borderTop: 'none',
              maxHeight: '300px', // Crucial for large lists: Limit height and enable scrolling
              overflowY: 'auto', // Enables scrolling if options exceed max height
              backgroundColor: 'white',
