    console.log('Selected Value:', value);
    setSelectedFruit(value);
  };

  return (
    <div style={{ padding: '40px', fontFamily: 'Arial, sans-serif' }}>
      <h1>Smart Fruit Selector</h1>

      <Input 
        label="Select a Fruit"
        placeholder="e.g., App, Ban, or start typing..."
        onChange={handleFruitChange}
      />

      <div style={{ marginTop: '30px', padding: '15px', border: '1px solid #ddd', backgroundColor: '#f9f9f9' }}>
        <strong>Currently Selected:</strong> {selectedFruit || 'None selected'}
      </div>

