      <ul>
        <li>Type 'A' (Should show Apple, Apricot, Avocado, etc.)</li>
        <li>Type 'Z' (Should show nothing, dropdown disappears)</li>
        <li>Type a valid option (Dropdown closes)</li>
        <li>Type 'NonExistentFruit' (Shows "No options found" hint, error border applies)</li>
        <li>Click outside (Dropdown closes)</li>
      </ul>
    </div>
  );
